<div class="iv-filter">
 <label>Search<input name="q" value="<?php echo e(request('q')); ?>" maxlength="100" placeholder="Product, SKU or reference"></label>
 <label>Record type<select name="type"><option value="">All records</option><?php $__currentLoopData = $kinds; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $code=>$label): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($code); ?>" <?php if(request('type')===$code): echo 'selected'; endif; ?>><?php echo e($label); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></label>
 <label>Direction<select name="direction"><option value="">All</option><?php $__currentLoopData = ['in'=>'Increase','out'=>'Decrease']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $value=>$label): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($value); ?>" <?php if(request('direction')===$value): echo 'selected'; endif; ?>><?php echo e($label); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></label>
 <label>Recorded from<input type="date" name="from" value="<?php echo e(request('from')); ?>"></label><label>Recorded to<input type="date" name="to" value="<?php echo e(request('to')); ?>"></label>
 <label>Rows<select name="per_page"><?php $__currentLoopData = [10,25,50,100]; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $n): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($n); ?>" <?php if((int)request('per_page',25)===$n): echo 'selected'; endif; ?>><?php echo e($n); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></label>
 <button class="iv-btn iv-active" type="submit">Filter</button>
</div>
